def f(g):
    H=len(g);W=len(g[0]);seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)];comp=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x));comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[y][x] and (ny,nx) not in seen: st.append((ny,nx))
                comps.append((g[comp[0][0]][comp[0][1]],comp))
    # noisy template: rect whose interior contains >=1 cell of its color AND >=1 nonzero... simply: has interior cells
    # distinguish: plain rects have NO interior cells of their own color; noisy have many. Use count > 0.
    tinfo=None
    for c,comp in comps:
        rs=[p[0] for p in comp]; cls=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        inn={(i-r0,j-c0) for i in range(r0+1,r1) for j in range(c0+1,c1) if g[i][j]==c}
        if inn:
            tinfo=(r0,c0,h:=r1-r0+1,w:=c1-c0+1,{p for p in inn})
    if tinfo is None: return [row[:] for row in g]
    rt,ct,h,w,tpl=tinfo
    out=[row[:] for row in g]
    for c,comp in comps:
        rs=[p[0] for p in comp]; cls=[p[1] for p in comp]
        r0,r1,c0,c1=min(rs),max(rs),min(cls),max(cls)
        hh,ww=r1-r0+1,c1-c0+1
        if (hh,ww)!=(h,w): continue
        for dr,dc in tpl:
            rr,cc=r0+dr,c0+dc
            if 0<=rr<hh and 0<=cc<ww: out[rr][cc]=c
    return out
